/* =====================================================================
   PART 8 — ANAPHYLAXIS · GI/HEPATIC · OBSTETRIC EMERGENCIES
            NEONATAL ICU · PAEDIATRIC PROGRAMMES · MISCELLANEOUS
   ===================================================================== */

/* ================= ANAPHYLAXIS ================= */
R({ id:'adrenaline-im-anaph', n:'Adrenaline IM — ANAPHYLAXIS (FIRST-LINE, NO DELAY)', sys:'anaphylaxis', cls:'Non-selective α/β adrenergic agonist',
  ind:'Anaphylaxis of any cause — drug, food, insect sting, latex, ASV/antitoxin reaction, contrast. THE ONLY FIRST-LINE TREATMENT', pop:'all', risk:5,
  d:{t:'mg', lo:0.15, hi:0.5, cap:0.5, rep:'IM into the anterolateral thigh, repeated EVERY 5 MINUTES if there is no improvement'},
  fx:[{s:'1 mg/mL (1:1000)', c:1, u:'mg', p:'1 mL ampoule — draw the exact volume in a 1 mL syringe', b:'Adrenaline IP — Neon, Vins, BDH, Troikaa; Anapen/EpiPen auto-injectors are NOT marketed in India', r:'IM', hl:1}],
  admin:'IM into the MID-ANTEROLATERAL THIGH (through clothing if necessary): adult and child >12 yr 0.5 mg (0.5 mL); child 6–12 yr 0.3 mg (0.3 mL); 6 months–6 yr 0.15 mg (0.15 mL); infant <6 months 0.1–0.15 mg (0.1–0.15 mL); or 10 mcg/kg (0.01 mL/kg of 1:1000) in any child. REPEAT EVERY 5 MINUTES until there is improvement. Simultaneously: lay the patient flat with legs raised (sit up if breathing is difficult, never stand them up), give high-flow oxygen, obtain IV/IO access and give 0.9% NaCl 20 mL/kg rapidly (1–2 L in an adult).',
  dil:'NO DILUTION for the IM route — use the 1 mg/mL ampoule as supplied.',
  warn:['NEVER GIVE ADRENALINE IV AS A BOLUS IN A PATIENT WITH A PULSE unless you are an experienced clinician with continuous ECG/BP monitoring and a 1:10,000 (or 1:100,000) dilution — inadvertent IV bolus of 1:1000 causes fatal arrhythmias, hypertension and pulmonary oedema.','ANTIHISTAMINES AND CORTICOSTEROIDS ARE SECOND-LINE AND MUST NEVER DELAY ADRENALINE.','Do not let the patient sit or stand abruptly — "empty ventricle syndrome" causes sudden cardiovascular collapse.','Refractory anaphylaxis (no response after 3–5 IM doses): start an adrenaline INFUSION 0.05–0.5 mcg/kg/min (or 0.1 mcg/kg/min in children), give large-volume fluids, and consider IV adrenaline boluses of 50–100 mcg (adult) given by an experienced clinician with continuous monitoring.','Patients on β-blockers may not respond to adrenaline — give GLUCAGON 1–5 mg IV over 5 min then 5–15 mcg/min infusion.','BIPHASIC REACTIONS occur in 1–20% after 1–72 h — observe for at least 6–12 h (24 h if severe, on β-blockers, asthmatic, or with a late reaction).','Tranexamic acid 1 g IV and vasopressin/terlipressin have been used for refractory anaphylaxis.','Prescribe an adrenaline auto-injector equivalent plan (a prefilled 1 mg/mL syringe with clear written instructions) and refer to allergy; give a written anaphylaxis action plan.'],
  ref:['WAO-ANAPHYLAXIS','AHA2025-ANAPHYLAXIS','RESCUS-ANAPH','IAP-ANAPHYLAXIS','BNF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'anaphylaxis-adjuncts', n:'Anaphylaxis — second-line and adjunctive drugs', sys:'anaphylaxis', cls:'H1-antihistamine + glucocorticoid + β2 agonist + fluid',
  ind:'Symptomatic relief after adrenaline has been given; bronchospasm; prevention of protracted/biphasic reactions (corticosteroid)', pop:'all', risk:3,
  d:{t:'text', text:'A COMBINATION regimen - each drug below is dosed separately. Every one of them is given ONLY AFTER adrenaline. Adult: chlorpheniramine 10 mg IV + hydrocortisone 200 mg IV + salbutamol 5 mg nebulised. Child: chlorpheniramine 0.1-0.2 mg/kg (max 10 mg) + hydrocortisone 2 mg/kg (max 200 mg) + salbutamol 2.5 mg nebulised. Fluid 20 mL/kg repeated.'},
  fx:[{s:'10 mg/mL chlorpheniramine', c:10, u:'mg', p:'1 mL ampoule (10 mg)', b:'Avil (Sanofi), Chlorpheniramine IP — Neon/Samarth', r:'IV/IM/PO', hl:1, use:'fixed', give:'Adult 10 mg (1 mL) IV slowly over 1-2 min. Child 0.1-0.2 mg/kg (max 10 mg). Sedating - not first-line and never a substitute for adrenaline.'},
      {s:'100 mg hydrocortisone vial', c:50, u:'mg', p:'reconstitute with 2 mL WFI → 50 mg/mL', b:'Hydrocort (Samarth), Solu-Cortef', r:'IV', use:'fixed', give:'Adult 200 mg (4 mL of the reconstituted 50 mg/mL) IV, then 200 mg/24 h. Child 2 mg/kg (max 200 mg). Onset 4-6 h.'},
      {s:'4 mg/mL dexamethasone', c:4, u:'mg', p:'2 mL ampoule (8 mg)', b:'Dexamethasone IP — Neon; Dexona, Decdan', r:'IV/PO', use:'fixed', give:'Adult 8-16 mg (2-4 mL) IV. Child 0.15-0.6 mg/kg (max 16 mg). An alternative to hydrocortisone.'},
      {s:'1 mg/mL salbutamol neb solution', c:1, u:'mg', p:'2.5 mL respule (2.5 mg), 5 mg/2.5 mL', b:'Asthalin Respules, Levolin', r:'NEB', use:'fixed', give:'Adult 5 mg, child <5 years 2.5 mg, nebulised driven by OXYGEN for persistent bronchospasm. It does NOT treat upper-airway (laryngeal) oedema - that needs adrenaline.'},
      {s:'0.9% sodium chloride', c:1, u:'ml', p:'500 mL / 1000 mL bag', b:'Normal Saline IP', r:'IV', use:'fixed', give:'20 mL/kg IV rapidly (1-2 L in adults), repeated as needed. Anaphylactic shock is distributive AND hypovolaemic - up to 35% of the circulating volume shifts into the interstitium.'},
      {s:'Glucagon 1 mg vial (β-blocked patients)', c:1, u:'mg', p:'vial with 1 mL diluent', b:'Glucagon (Novo Nordisk) — limited availability', r:'IV/IM/SC', use:'fixed', give:'1-2 mg IV over 5 min, then 5-15 mcg/min, for patients on β-blockers who do not respond to repeated adrenaline. Vomiting is common - protect the airway.'}],
  admin:'AFTER adrenaline: chlorpheniramine 10 mg IV slowly (or 0.1–0.2 mg/kg in a child, max 10 mg) + hydrocortisone 200 mg IV (child 2 mg/kg, max 200 mg) or dexamethasone 8–16 mg IV. Salbutamol 5 mg (child 2.5 mg) nebulised for persistent wheeze. Fluids 20 mL/kg of 0.9% NaCl repeated as needed. Glucagon 1–5 mg IV over 5 min then 5–15 mcg/min for patients on β-blockers who do not respond to adrenaline.',
  dil:'Dilute chlorpheniramine in 10 mL NS and give over 1–2 min.',
  warn:['NONE of these drugs treat upper-airway obstruction or shock — ADRENALINE DOES.','Hydrocortisone has a 4–6 h onset of action; the evidence that steroids prevent biphasic reactions is weak, but they remain standard practice.','Ranitidine (an H2 antagonist) 50 mg IV may be added; H2 blockers alone have no role.','Monitor for at least 6–12 h; give a written action plan and an adrenaline prescription on discharge.','Adrenaline must be given IM, not SC — SC absorption is far slower and unreliable in shock.'],
  ref:['WAO-ANAPHYLAXIS','AHA2025-ANAPHYLAXIS','RESCUS-ANAPH','IAP-ANAPHYLAXIS','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

/* ================= GI / HEPATIC ================= */
R({ id:'octreotide-variceal', n:'Octreotide — acute variceal bleed', sys:'gi', cls:'Somatostatin analogue (splanchnic vasoconstrictor)',
  ind:'Acute oesophageal/gastric variceal haemorrhage in portal hypertension — started BEFORE endoscopy', pop:'adult', risk:4, inf:true,
  d:{t:'mcghr', lo:25, hi:50, capDay:1200},
  diln:[{l:'500 mcg in 50 mL NS → 10 mcg/mL (50 mcg/h = 5 mL/h)', amt:500, in:50, u:'mcg', bag:'50 mL 0.9% NaCl'},
        {l:'1000 mcg in 100 mL NS → 10 mcg/mL', amt:1000, in:100, u:'mcg', bag:'100 mL 0.9% NaCl'}],
  fx:[{s:'50 mcg/mL', c:50, u:'mcg', p:'1 mL ampoule (50 mcg)', b:'Octride (Samarth), Sandostatin (Novartis), Octreo, Octide', r:'IV/SC', hl:1},
      {s:'100 mcg/mL', c:100, u:'mcg', p:'1 mL ampoule (100 mcg)', b:'Octride 100 mcg, Sandostatin 100 mcg', r:'IV/SC'},
      {s:'10 / 20 / 30 mg LAR depot (monthly)', c:10000, u:'mcg', p:'vial with diluent', b:'Sandostatin LAR, Octride LAR', r:'IM-deep', own:{text:'The LAR depot (10/20/30 mg deep IM once monthly) is for acromegaly, carcinoid syndrome and neuroendocrine tumours. It has NO role in acute variceal bleeding and must NOT be used here.'}}],
  admin:'50 mcg IV bolus, then 25–50 mcg/h IV infusion for 2–5 days. Combine with a vasoactive drug alternative (terlipressin) or as an alternative to it, PLUS ceftriaxone 1 g IV daily × 7 days, PLUS restrictive transfusion (target Hb 7–8 g/dL), PLUS endoscopy within 12 h.',
  dil:'Dilute in NS; compatible; use within 24 h.',
  warn:['Terlipressin is superior for bleeding control in many Indian centres; octreotide is the alternative when terlipressin is contraindicated (ischaemic heart disease, pregnancy, peripheral vascular disease).','Hyperglycaemia/hypoglycaemia, bradycardia, QT prolongation, steatorrhoea, gallstones with prolonged use.','Restrictive transfusion (Hb 7–8 g/dL) reduces rebleeding and mortality compared with a liberal strategy.','Antibiotic prophylaxis (ceftriaxone) reduces rebleeding, infection and mortality — it is mandatory, not optional.'],
  ref:['AASLD-VARICEAL','EASL-LIVER','ISCCM-LIVER','BSG-VARICEAL'] });

R({ id:'pantoprazole-gib', n:'Pantoprazole — upper GI bleeding', sys:'gi', cls:'Proton-pump inhibitor (irreversible H⁺/K⁺-ATPase inhibitor)',
  ind:'Bleeding peptic ulcer after endoscopic therapy, stress ulcer prophylaxis, severe GERD/oesophagitis, Zollinger–Ellison syndrome', pop:'adult', risk:2,
  d:{t:'mg', lo:40, hi:80, capDay:240, rep:'high-risk ulcer: 80 mg IV bolus then 8 mg/h × 72 h; prophylaxis: 40 mg IV once daily'},
  fx:[{s:'40 mg vial', c:4, u:'mg', p:'40 mg vial reconstituted with 10 mL NS → 4 mg/mL', b:'Pan (Alkem), Pantocid (Sun), Pantop (Cipla), Pantocid-40, Pantoprazole IP — Intas/Macleods', r:'IV/PO', hl:1, prep:'Reconstitute 40 mg with 10 mL 0.9% NaCl → 4 mg/mL; for infusion add to 100 mL NS (final 0.4 mg/mL) and give over 15 min'},
      {s:'40 mg tablet (enteric-coated)', c:40, u:'mg', p:'strip of 10/15', b:'Pan 40, Pantocid 40, Pantop 40, Pantop-D', r:'PO'},
      {s:'40 mg/mL concentrate (some brands)', c:40, u:'mg', p:'10 mL vial', b:'Pantoprazole concentrate', r:'IV'}],
  admin:'Acute ulcer bleed with high-risk stigmata after endoscopic haemostasis: 80 mg IV bolus over 15–30 min, then 8 mg/h continuous infusion for 72 h, then 40 mg PO/IV daily. Intermittent 40 mg IV BD is non-inferior in many settings and is widely used in India. Stress-ulcer prophylaxis: 40 mg IV/PO once daily.',
  dil:'Reconstitute with NS only (the supplied diluent is 0.9% NaCl); use within 12 h; do not mix with other drugs.',
  warn:['Do not use routine stress-ulcer prophylaxis in all ICU patients — restrict to mechanical ventilation >48 h, coagulopathy, prior GI bleed, TBI/spinal cord injury, burns >35%, sepsis, high-dose steroids + NSAIDs. Unnecessary PPIs increase the risk of C. difficile, pneumonia and multidrug-resistant colonisation.','Long-term PPI use: hypomagnesaemia, vitamin B12 deficiency, bone fracture, CKI, small intestinal bacterial overgrowth.','Pantoprazole has the lowest CYP2C19 interaction of the PPIs — preferred with clopidogrel.','Recheck Hb, and give endoscopic therapy before starting the high-dose infusion.'],
  ref:['ACG-UGIB','ESGE-UGIB','ISCCM-SUP','BNF'] });

R({ id:'lactulose-he', n:'Lactulose + rifaximin — hepatic encephalopathy', sys:'gi', cls:'Non-absorbable disaccharide (osmotic laxative, ammonia trap) + non-absorbable antibiotic',
  ind:'Hepatic encephalopathy (overt or covert) in cirrhosis or acute liver failure; prevention of recurrence', pop:'adult', risk:2,
  d:{t:'ml', lo:15, hi:45, capDay:240, rep:'15–30 mL PO/NG every 1–2 h until 2–3 soft stools per day, then 15–30 mL 2–3 times daily'},
  fx:[{s:'667 mg/mL (10 g/15 mL) lactulose solution', c:667, u:'mg', p:'100 mL / 200 mL / 450 mL bottle', b:'Duphalac (Abbott/Mylan), Looz (Alkem), Enulose, Lactulose IP — Cadila/Samarth', r:'PO/PR', hl:1},
      {s:'400 mg rifaximin tablet', c:400, u:'mg', p:'strip of 10', b:'Rifagut (Sun), Rifaxigut (Alkem), Rifacol (Torrent), Sibofix', r:'PO', use:'fixed', give:'Rifaximin 400 mg PO three times daily (or 550 mg twice daily) added to lactulose for recurrent hepatic encephalopathy - it is an adjunct, not a substitute.'},
      {s:'550 mg rifaximin tablet', c:550, u:'mg', p:'strip of 14', b:'Rifagut 550, Rifaxigut 550', r:'PO', use:'fixed', give:'Rifaximin 550 mg PO twice daily added to lactulose for prevention of recurrent hepatic encephalopathy.'},
      {s:'L-ornithine L-aspartate 5 g/10 mL ampoule', c:500, u:'mg', p:'10 mL ampoule (5 g)', b:'Hepamerz (Abbott), Hepagrand, LOLA (Intas)', r:'IV', use:'fixed', give:'LOLA 10-20 g IV daily (2-4 ampoules) in 250 mL of NS or dextrose over 4 h, for up to 7 days in overt hepatic encephalopathy - an adjunct to lactulose, not a replacement.'},
      {s:'Lactulose retention enema (300 mL lactulose in 700 mL water)', c:667, u:'mg', p:'compounded - 1 L total volume', b:'Pharmacy preparation', r:'PR', use:'fixed', give:'When the oral route is unavailable: 300 mL of lactulose in 700 mL of water as a retention enema, retained for 30-60 min, every 6-8 h. Position the patient on the left side with the head down.'}],
  admin:'Lactulose 15–30 mL (10–20 g) PO/NG every 1–2 h until the patient has 2–3 soft stools/day, then reduce to 15–30 mL 2–3 times daily to maintain 2–3 soft stools. Add rifaximin 400 mg TDS (or 550 mg BD) for overt HE and for secondary prophylaxis. LOLA 20 g/day IV (4 ampoules in 250 mL NS over 4 h) may be added in acute episodes. If the patient is obtunded, give a retention enema: 300 mL of lactulose in 700 mL of water, retained for 30–60 min, every 4–6 h.',
  dil:'Lactulose may be diluted in water or juice; LOLA must be diluted in 250 mL of NS or D5W and infused over 4 h (max 5 g/h).',
  warn:['Do NOT over-purge — 2–3 soft stools/day is the target; severe diarrhoea causes dehydration, hypokalaemia and worsens HE.','Search for and treat the precipitant: infection (SBP, UTI, pneumonia), GI bleeding, electrolyte disturbance, constipation, sedatives, TIPS, HCC, renal failure.','Avoid benzodiazepines and opioids — they precipitate and mask HE.','Correct hypokalaemia and alkalosis (both increase renal ammonia production).','LOLA infusion >5 g/h causes nausea and vomiting; contraindicated in severe renal failure (creatinine >3 mg/dL).','Protein restriction is OUTDATED — give 1.2–1.5 g/kg/day of protein with frequent small meals and a late-night snack.','Rifaximin is expensive but reduces re-admission — cost-effectiveness improves with recurrent HE.'],
  ref:['AASLD-HE','EASL-HE','ISCCM-LIVER','BSG-HE'] });

R({ id:'ondansetron', n:'Ondansetron', sys:'gi', cls:'Selective 5-HT3 receptor antagonist',
  ind:'Nausea and vomiting — post-operative, chemotherapy, gastroenteritis, opioid-induced, hyperemesis, raised ICP', pop:'all', risk:2,
  d:{t:'mgkg', lo:0.1, hi:0.15, cap:8, capDay:24, rep:'4–8 mg IV/PO every 8 h (child 0.1–0.15 mg/kg, max 4 mg per dose, max 8 mg/day if <3 years)'},
  fx:[{s:'2 mg/mL', c:2, u:'mg', p:'2 mL ampoule (4 mg), 4 mL ampoule (8 mg)', b:'Emeset (Cipla), Ondem (Alkem), Vomikind (Mankind), Perimidine, Ondansetron IP — Neon/Intas', r:'IV/IM/PO', hl:1},
      {s:'4 mg / 8 mg mouth-dissolving tablets', c:4, u:'mg', p:'strip of 10', b:'Emeset MD, Ondem MD, Vomikind MD', r:'PO/SL'},
      {s:'2 mg/5 mL syrup', c:0.4, u:'mg', p:'30 mL / 60 mL bottle', b:'Emeset syrup, Ondem syrup', r:'PO'}],
  admin:'Adult 4–8 mg IV over 2–5 min every 8 h. Child >40 kg 4 mg; 15–40 kg 4 mg; 8–15 kg 2.5 mg; <8 kg 2 mg (0.15 mg/kg). Chemotherapy 8 mg IV before, then 8 mg 12 h later, then 8 mg BD orally × 5 days.',
  dil:'Ready to use; may be diluted in 50–100 mL NS/D5W and infused over 15 min.',
  warn:['QT PROLONGATION and torsades — avoid IV doses >16 mg as a single bolus, avoid in patients with congenital long QT, hypokalaemia, hypomagnesaemia or on other QT-prolonging drugs; correct electrolytes first.','Constipation, headache, flushing; extrapyramidal reactions rarely.','Serotonin syndrome when combined with other serotonergic drugs.','A single 4–8 mg dose in paediatric gastroenteritis reduces vomiting and the need for IV fluids — but it must NOT replace oral rehydration therapy.'],
  ref:['BNF','BNFC','ASHP-CINV','IAP-GE','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG'] });

R({ id:'metoclopramide', n:'Metoclopramide', sys:'gi', cls:'D2 antagonist + 5-HT4 agonist + weak 5-HT3 antagonist (prokinetic and antiemetic)',
  ind:'Gastroparesis, delayed gastric emptying in the ICU, nausea/vomiting, migraine adjunct, facilitation of small-bowel intubation, antiemetic prophylaxis', pop:'adult', risk:3,
  d:{t:'mg', lo:10, hi:20, capDay:30, rep:'10 mg IV/PO every 8 h (max 30 mg/day; reduce in the elderly and in renal impairment)'},
  fx:[{s:'5 mg/mL', c:5, u:'mg', p:'2 mL ampoule (10 mg)', b:'Perinorm (Ipca), Metoclopramide IP — Neon/Vamcare/Samarth; Reglan, Metpra', r:'IV/IM/PO', hl:1},
      {s:'10 mg tablet', c:10, u:'mg', p:'strip of 10', b:'Perinorm 10, Metoclopramide 10, Reglan 10', r:'PO'},
      {s:'5 mg/5 mL syrup', c:1, u:'mg', p:'60 mL bottle', b:'Perinorm syrup, Metoclopramide syrup', r:'PO'}],
  admin:'10 mg IV over 1–2 min (or IM) every 8 h. ICU prokinetic: 10 mg IV every 8 h, or 5–10 mg PO/NG every 6 h. Reduce the dose by 50% if CrCl <40 mL/min.',
  dil:'Give IV over at least 1–2 min (rapid injection causes akathisia and anxiety); may be diluted in 50 mL NS.',
  warn:['EXTRAPYRAMIDAL REACTIONS — acute dystonia (oculogyric crisis, torticollis, trismus), akathisia and, rarely, tardive dyskinesia. Risk is highest in patients <30 years, on high doses, and with prolonged use. Treat acute dystonia with benzhexol 5–10 mg PO/IM, promethazine 25 mg IM or diphenhydramine 25–50 mg IV.','FDA/CDSCO boxed warning: tardive dyskinesia risk rises with duration >12 weeks and cumulative dose; do not exceed 12 weeks.','Contraindicated in GI obstruction/perforation/haemorrhage, phaeochromocytoma (hypertensive crisis), epilepsy, and with antipsychotics.','Neuroleptic malignant syndrome; methaemoglobinaemia with overdose.','Do not combine with antipsychotics (additive EPS).','Serotonin syndrome with other serotonergic drugs.','Restlessness, drowsiness, diarrhoea; raised prolactin (galactorrhoea, gynaecomastia, amenorrhoea).'],
  ref:['BNF','ISCCM-NUTRITION','FDA-METOCLOPRAMIDE','MARINO'] });

R({ id:'neostigmine-ogilvie', n:'Neostigmine — acute colonic pseudo-obstruction (Ogilvie syndrome)', sys:'gi', cls:'Acetylcholinesterase inhibitor (parasympathomimetic)',
  ind:'Acute colonic pseudo-obstruction with caecal diameter >10–12 cm failing 24–48 h of conservative management', pop:'adult', risk:5,
  d:{t:'mg', v:2, cap:2.5, rep:'2 mg IV over 3–5 min once; may repeat once after 10–20 min if there is no response'},
  fx:[{s:'0.5 mg/mL', c:0.5, u:'mg', p:'1 mL ampoule (0.5 mg) — 4 ampoules needed per dose', b:'Neostigmine IP — Abbott, Samarth, Neon; Neoton, Prostigmin', r:'IV', hl:1},
      {s:'1 mg/mL atropine (must be drawn up and ready)', c:1, u:'mg', p:'1 mL ampoule', b:'Atropine IP — Neon, Samarth', r:'IV', own:{lo:0.6,hi:1,u:'mg',l:'ATROPINE 0.6–1 mg — draw up and keep at the bedside BEFORE giving neostigmine, and give it immediately for bradycardia. THIS IS A DIFFERENT DRUG AT A DIFFERENT DOSE.'}}],
  admin:'Ensure continuous ECG monitoring, IV access, and ATROPINE 0.6–1 mg drawn up at the bedside BEFORE giving neostigmine. Give 2 mg IV slowly over 3–5 min; the patient should remain on a bedpan/commode — defaecation typically occurs within 2–30 min. Repeat once after 10–20 min if there is no response.',
  dil:'May be diluted to 5 mL with NS.',
  warn:['SEVERE BRADYCARDIA AND ASYSTOLE — atropine must be immediately available; 10–20% of patients require it.','Contraindicated in mechanical obstruction, peritonitis/perforation, recent MI, active bronchospasm/asthma, peptic ulcer disease, pregnancy, and in patients on β-blockers (relative).','First exclude mechanical obstruction and toxic megacolon (CT colonography/endoscopy), and correct hypokalaemia, hypomagnesaemia, hypocalcaemia, hypothyroidism, and stop opioids/anticholinergics/causal drugs.','Conservative management (NPO, NG tube, mobilisation, correct electrolytes, stop offending drugs, treat sepsis) is first-line for 24–48 h.','If neostigmine fails, perform colonoscopic decompression or surgery.'],
  ref:['ACG-OGILVIE','ASGE-OGILVIE','BNF','TINTINALLI'] });

R({ id:'hyoscine-drotaverine', n:'Hyoscine butylbromide / Drotaverine — visceral colic', sys:'gi', cls:'Antimuscarinic / phosphodiesterase-4 inhibitor smooth-muscle relaxant',
  ind:'Biliary colic, renal colic, intestinal spasm, uterine cramping; endoscopy adjunct', pop:'adult', risk:2,
  d:{t:'mg', lo:20, hi:40, capDay:120, rep:'hyoscine butylbromide 20 mg IV/IM every 6–8 h; drotaverine 40–80 mg IV/IM every 8 h'},
  fx:[{s:'20 mg/mL hyoscine butylbromide', c:20, u:'mg', p:'1 mL ampoule (20 mg)', b:'Buscopan (Boehringer Ingelheim), Hyoscine-N-butylbromide IP — Samarth/Neon; Buscopan Forte', r:'IV/IM/PO', hl:1},
      {s:'40 mg/mL drotaverine', c:40, u:'mg', p:'2 mL ampoule (80 mg)', b:'Drotaverine (Sun/Mankind), Drotin, Drotan, Drotaverine HCl IP', r:'IV/IM/PO', own:{lo:40,hi:80,u:'mg',l:'DROTAVERRINE 40–80 mg IV slowly or IM every 8 h (max 240 mg/day) — an alternative antispasmodic to hyoscine.'}},
      {s:'10 mg drotaverine + 250 mg paracetamol tablet', c:10, u:'mg', p:'strip', b:'Drotin-M, Drotaverine + paracetamol combinations', r:'PO', own:{lo:10,hi:20,u:'mg',l:'Combination tablet (drotaverine 10 mg + paracetamol 250 mg): 1–2 tablets PO 8-hourly for mild colic. EACH TABLET CONTAINS 250 mg OF PARACETAMOL — count it towards the 4 g/24 h ceiling.'}},
      {s:'10 mg/mL dicyclomine', c:10, u:'mg', p:'2 mL ampoule (20 mg)', b:'Dicyclomine IP (Cyclopam, Dicyclomine Neon)', r:'IM', own:{lo:10,hi:20,u:'mg',l:'DICYCLOMINE 10–20 mg IM (adult) as an alternative antispasmodic. Avoid in infants (apnoea), glaucoma, myasthenia gravis, obstructive uropathy and severe ulcerative colitis.'}}],
  admin:'Hyoscine butylbromide 20 mg IV slowly (over 1 min) or IM, repeatable after 30 min, max 100 mg/day. Drotaverine 40–80 mg IV slowly or IM every 8 h. Renal colic: combine with an NSAID (diclofenac 75 mg IM) or an opioid.',
  dil:'Give IV slowly; dilute in 10–20 mL NS if desired.',
  warn:['Hyoscine: tachycardia, dry mouth, blurred vision, urinary retention; contraindicated in glaucoma, paralytic ileus, myasthenia gravis, megacolon, and prostatic hypertrophy.','Drotaverine IV must be given SLOWLY and with the patient lying down — rapid injection causes hypotension and collapse.','Do not mask the pain of a surgical abdomen — reassess for peritonitis, obstruction or a leaking aneurysm.','Drotaverine is widely used in India but is not licensed in many countries; the evidence base is moderate.'],
  ref:['BNF','IAP-COLIC','TINTINALLI','IAP-STG'] });

R({ id:'nac-alf', n:'N-acetylcysteine — non-paracetamol acute liver failure', sys:'gi', cls:'Antioxidant / microcirculatory agent',
  ind:'Early-stage non-paracetamol acute liver failure (improves transplant-free survival in grade I–II encephalopathy)', pop:'adult', risk:3,
  d:{t:'mgkgday', lo:100, hi:100, capDay:7000, rep:'100 mg/kg/day IV continuous infusion for 5–7 days (or until transplantation/recovery)'},
  fx:[{s:'200 mg/mL (20%)', c:200, u:'mg', p:'2 g/10 mL vial', b:'Mucomix (Sun), NAC (Samarth), Mucolite injectable', r:'IV', hl:1}],
  admin:'100 mg/kg/day as a continuous IV infusion (≈7 g/day for a 70-kg adult, i.e. 3.5 vials) in 5% dextrose, or the modified 3-bag paracetamol regimen (150 mg/kg over 1 h → 50 mg/kg over 4 h → 100 mg/kg over 16 h) continued for 5–7 days.',
  dil:'Dilute in 5% dextrose or NS; final concentration ≤30 mg/mL.',
  warn:['Benefit is demonstrated mainly in EARLY (grade I–II) encephalopathy — it may not help grade III–IV.','Anaphylactoid reactions during the loading phase — stop, treat with an antihistamine, restart more slowly.','Refer early for liver transplant assessment; do not delay transfer while giving NAC.','Monitor INR, bilirubin, ammonia, glucose, phosphate, lactate and creatinine — apply the King\'s College or Clichy criteria.'],
  ref:['AASLD-ALF','EASL-ALF','ISCCM-LIVER','BNF'] });

/* ================= OBSTETRIC EMERGENCIES ================= */
R({ id:'mgso4-eclampsia', n:'Magnesium sulfate — eclampsia and severe pre-eclampsia', sys:'obs', cls:'Membrane stabiliser / calcium antagonist / NMDA antagonist',
  ind:'Treatment and prophylaxis of eclamptic seizures; neuroprotection before preterm birth (<32 weeks)', pop:'adult', risk:5, inf:true,
  d:{t:'g', lo:4, hi:10, rep:'ZUSPAN: 4 g IV over 5–10 min then 1 g/h × 24 h. PRITCHARD: 4 g IV over 5–10 min + 10 g IM (5 g in each buttock) then 5 g IM every 4 h'},
  diln:[{l:'10 g in 500 mL NS → 20 mg/mL (Zuspan maintenance: 50 mL/h = 1 g/h)', amt:10, in:500, u:'g', bag:'500 mL 0.9% NaCl'},
        {l:'20 g in 500 mL NS → 40 mg/mL (fluid-restricted)', amt:20, in:500, u:'g', bag:'500 mL 0.9% NaCl'}],
  fx:[{s:'500 mg/mL (50%)', c:500, u:'mg', p:'2 mL ampoule (1 g), 10 mL vial (5 g)', b:'Magnesium Sulphate IP — Neon, Samarth, Sisco, Claris; MgSO₄ 50%', r:'IV/IM', hl:1},
      {s:'200 mg/mL (20%)', c:200, u:'mg', p:'10 mL ampoule (2 g)', b:'MgSO₄ 20% — Samarth', r:'IV/IM'},
      {s:'250 mg/mL (25%)', c:250, u:'mg', p:'10 mL vial (2.5 g)', b:'MgSO₄ 25%', r:'IV'}],
  admin:'ZUSPAN REGIMEN: loading 4 g IV over 5–10 min (8 mL of 50% in 92 mL NS, or 4 ampoules of 1 g), then 1 g/h IV infusion for 24 h after delivery or after the last seizure. PRITCHARD REGIMEN (no infusion pump needed): 4 g IV slowly over 5–10 min PLUS 10 g IM (5 g = 10 mL of 50% into each buttock with a long needle), then 5 g IM every 4 h into alternating buttocks for 24 h after the last seizure. Recurrent seizure: give a further 2 g IV over 5 min. Fetal neuroprotection <32 weeks: 4 g IV over 20–30 min then 1 g/h for 12–24 h.',
  dil:'For the IV load, dilute 4 g (8 mL of 50%) in 92 mL of NS to make 100 mL and infuse over 10 min. IM injection of the 50% solution is painful — 1% lignocaine may be added.',
  warn:['MONITOR BEFORE EVERY DOSE: (1) patellar reflexes present, (2) respiratory rate ≥16/min, (3) urine output ≥25–30 mL/h (≥100 mL over 4 h). Withhold the dose if any is abnormal and check a serum magnesium level.','ANTIDOTE: calcium gluconate 10% 10 mL IV over 10 min — keep one ampoule drawn up at the bedside.','Reduce or stop the infusion in renal impairment (magnesium is renally excreted) — check a level after 4–6 h if oliguric.','Maternal flushing, sweating, nausea, muscle weakness, drowsiness are expected; loss of reflexes at 3.5–5 mmol/L, respiratory paralysis >5 mmol/L, cardiac arrest >7 mmol/L.','Magnesium is NOT an antihypertensive — treat severe hypertension separately with labetalol, nifedipine or hydralazine.','Deliver the baby — magnesium and antihypertensives are stabilising measures only. Delivery is the definitive treatment for eclampsia.','Continue for 24 h after delivery or after the last seizure, whichever is later.'],
  ref:['ACOG-ECLAMPSIA','WHO-ECLAMPSIA','NICE-NG133','FOGSI','MAGPIE'] });

R({ id:'oxytocin-pph', n:'Oxytocin — post-partum haemorrhage', sys:'obs', cls:'Uterotonic (oxytocin receptor agonist)',
  ind:'Prevention and first-line treatment of post-partum haemorrhage from uterine atony; induction/augmentation of labour', pop:'adult', risk:4,
  d:{t:'units', lo:5, hi:10, capDay:60, rep:'5 IU slow IV (over at least 30 s) or 10 IU IM after delivery of the anterior shoulder; then 20–40 IU in 500–1000 mL NS at 40–60 mL/h'},
  fx:[{s:'10 IU/mL', c:10, u:'units', p:'1 mL ampoule (10 IU)', b:'Oxytocin IP — Neon, Samarth, Vins, Claris; Syntocinon (Novartis), Oxtin, Pitocin', r:'IV/IM', hl:1},
      {s:'5 IU/mL', c:5, u:'units', p:'1 mL ampoule (5 IU)', b:'Oxytocin 5 IU/mL — some brands', r:'IV/IM'},
      {s:'40 IU/mL for infusion', c:40, u:'units', p:'1 mL ampoule (40 IU)', b:'Oxytocin 40 IU/mL', r:'IV-inf'}],
  admin:'PROPHYLAXIS (active management of the third stage): 10 IU IM (or 5 IU slow IV in caesarean section) within 1 min of birth. TREATMENT of PPH: 5 IU slow IV over ≥30 s (never faster), then 20–40 IU in 500–1000 mL of NS at 40–60 mL/h (max 60 IU/24 h). Simultaneously: bimanual uterine massage, empty the bladder, secure two large-bore IV lines, crossmatch, give TXA 1 g IV, and escalate to second-line uterotonics.',
  dil:'Dilute for infusion in NS or D5W; stable 24 h.',
  warn:['NEVER give as a rapid IV bolus — causes acute hypotension, tachycardia, arrhythmias and cardiac arrest (the "oxytocin bolus" is a well-recognised cause of maternal death in caesarean sections).','Water intoxication and hyponatraemia with prolonged high-dose infusion (oxytocin has weak antidiuretic activity) — limit the total dose and the duration, and monitor Na⁺.','Tachyphylaxis after 4–6 h — do not keep escalating; move to a second-line uterotonic.','Antidiuretic effect; nausea, vomiting, headache.','If bleeding continues after 40 IU, give carboprost/methylergometrine/misoprostol and proceed to mechanical measures (intrauterine balloon, B-Lynch suture, uterine artery embolisation, hysterectomy).'],
  ref:['WHO-PPH','ACOG-PPH','FOGSI-PPH','NICE-NG133','BNF'] });

R({ id:'methylergometrine', n:'Methylergometrine (methylergonovine)', sys:'obs', cls:'Ergot alkaloid — potent sustained uterotonic and vasoconstrictor',
  ind:'Second-line uterotonic for post-partum haemorrhage due to atony when oxytocin fails', pop:'adult', risk:4,
  d:{t:'mg', v:0.2, cap:1, rep:'0.2 mg IM (or slow IV over ≥60 s in life-threatening bleeding), repeatable every 2–4 h up to 5 doses (max 1 mg)'},
  fx:[{s:'0.2 mg/mL', c:0.2, u:'mg', p:'1 mL ampoule (0.2 mg)', b:'Methergine (Novartis), Methylergometrine IP — Neon/Samarth; Ergometrine (combined with oxytocin as Syntometrine 5 IU + 0.5 mg)', r:'IM/IV/PO', hl:1},
      {s:'0.125 mg tablet', c:0.125, u:'mg', p:'strip', b:'Methergine 0.125 mg tablets', r:'PO'}],
  admin:'0.2 mg IM (preferred) every 2–4 h as needed (max 5 doses). Slow IV over at least 60 s ONLY in life-threatening haemorrhage with BP monitoring.',
  dil:'Ready to use; protect from light (store refrigerated).',
  warn:['ABSOLUTELY CONTRAINDICATED IN HYPERTENSION, PRE-ECLAMPSIA, ECLAMPSIA AND CARDIAC DISEASE — it causes severe hypertension, stroke, myocardial infarction and pulmonary oedema.','Contraindicated with concurrent vasoconstrictors (including local anaesthetics with adrenaline), and in sepsis.','IV administration causes abrupt hypertension — reserve it for life-threatening bleeding and give it over ≥60 s.','Nausea, vomiting, abdominal pain, chest pain, headache.','Contraindicated in the first and second stages of labour (before delivery of the baby) — causes tetanic uterine contraction and fetal distress.','Ergotism with prolonged use: peripheral ischaemia and gangrene.','Contraindicated with strong CYP3A4 inhibitors (macrolides, azoles, protease inhibitors).'],
  ref:['WHO-PPH','ACOG-PPH','FOGSI-PPH','BNF'] });

R({ id:'carboprost', n:'Carboprost (15-methyl prostaglandin F2α)', sys:'obs', cls:'Prostaglandin F2α analogue — powerful uterotonic',
  ind:'Refractory post-partum haemorrhage due to atony (third-line, after oxytocin and methylergometrine/misoprostol)', pop:'adult', risk:4,
  d:{t:'mcg', v:250, cap:2000, rep:'250 mcg deep IM (or intramyometrial) every 15–90 min as needed, maximum 8 doses (2 mg)'},
  fx:[{s:'250 mcg/mL', c:250, u:'mcg', p:'1 mL ampoule (250 mcg) — availability in India is improving (Zydus/Cipla generics)', b:'Hemabate (Pfizer), Carboprost (Zydus/Cipla), Carboprost Tromethamine IP', r:'IM/intramyometrial', hl:1}],
  admin:'250 mcg deep IM every 15–90 min, maximum 8 doses (2 mg total). May be given intramyometrially (avoiding the uterine vessels) during caesarean section. Onset 2–5 min, peak 10–15 min, duration ~2 h.',
  dil:'Ready to use; keep refrigerated (2–8 °C).',
  warn:['CONTRAINDICATED IN ASTHMA — causes severe bronchospasm (relative contraindication in severe COPD).','Causes diarrhoea (in ~50%), vomiting, flushing, fever, hypertension, bronchospasm.','Avoid in hepatic, renal or cardiac disease and in active pelvic inflammatory.','Do not exceed 8 doses (2 mg).','Misoprostol 800–1000 mcg SL/PR is a cheaper, widely available alternative in India — it is often used first where carboprost is not stocked.'],
  ref:['WHO-PPH','ACOG-PPH','FOGSI-PPH','BNF'] });

R({ id:'misoprostol-pph', n:'Misoprostol — post-partum haemorrhage', sys:'obs', cls:'Prostaglandin E1 analogue',
  ind:'PPH when oxytocin is unavailable or ineffective; cervical ripening; medical abortion; missed miscarriage', pop:'adult', risk:3,
  d:{t:'mcg', lo:600, hi:1000, cap:1000, rep:'PPH treatment 800–1000 mcg sublingually (or 600 mcg orally); prophylaxis where oxytocin is unavailable 600 mcg PO'},
  fx:[{s:'200 mcg tablet', c:200, u:'mcg', p:'strip of 4', b:'Misoprost 200 mcg (Cipla), Cytotec (Pfizer), Miso, Misoprostol IP — Sun/Intas; Misodel (vaginal insert 200 mcg)', r:'PO/SL/PR/PV', hl:1},
      {s:'100 mcg tablet', c:100, u:'mcg', p:'strip', b:'Misoprostol 100 mcg', r:'PO/PV'}],
  admin:'PPH treatment: 800 mcg (four 200 mcg tablets) sublingually — absorption is faster and more reliable sublingually than orally in shock. Repeat after 3 h if bleeding persists (maximum 2 further doses). Cervical ripening/induction: 25 mcg PV 4-hourly (never 200 mcg for this indication in a viable pregnancy).',
  dil:'Sublingual administration requires the patient to hold the tablets under the tongue for 30 min.',
  warn:['Shivering and pyrexia (up to 40 °C) occur in ~50% — they are self-limiting and must not be mistaken for sepsis.','Diarrhoea, nausea, vomiting.','CONTRAINDICATED IN Viable PREGNANCY when used at abortifacient doses (uterine rupture, fetal death, teratogenicity — Möbius sequence, limb defects).','Do NOT use 800 mcg for cervical ripening or induction in a viable pregnancy — the induction dose is 25 mcg.','Uterine rupture risk in women with a previous caesarean scar.','Store below 30 °C; the tablets are stable and do not need a cold chain — a major advantage in rural India.'],
  ref:['WHO-PPH','ACOG-PPH','FOGSI-PPH','BNF'] });

R({ id:'betamethasone-fetal', n:'Betamethasone / Dexamethasone — antenatal corticosteroids', sys:'obs', cls:'Fluorinated glucocorticoid (crosses the placenta — minimal placental metabolism)',
  ind:'Threatened preterm birth between 24 and 34 weeks (and late preterm 34–36⁺⁶ weeks in selected cases) — reduces RDS, IVH, NEC and neonatal mortality', pop:'adult', risk:3,
  d:{t:'mg', v:12, cap:48, rep:'betamethasone 12 mg IM every 24 h × 2 doses; OR dexamethasone 6 mg IM every 12 h × 4 doses'},
  fx:[{s:'4 mg/mL betamethasone (as sodium phosphate + acetate)', c:4, u:'mg', p:'1 mL ampoule (4 mg), 2 mL ampoule (8 mg) — 12 mg needs 3 ampoules', b:'Betnesol (GSK), Celestone (MSD), Betamethasone IP — Neon/Samarth; Betnelan', r:'IM/IV/PO', hl:1},
      {s:'4 mg/mL dexamethasone', c:4, u:'mg', p:'1 mL / 2 mL ampoule', b:'Dexamethasone IP — Neon, Aristo; Dexona, Decdan', r:'IM/IV'}],
  admin:'BETAMETHASONE 12 mg IM every 24 h for 2 doses (the preferred regimen). Alternative where betamethasone is unavailable: DEXAMETHASONE 6 mg IM every 12 h for 4 doses. Optimal benefit occurs 24 h to 7 days after the first dose. A single rescue course may be given if >7–14 days have elapsed, the gestation is still <34 weeks and the risk of preterm birth is high.',
  dil:'Ready to use for deep IM injection.',
  warn:['Do NOT give more than one rescue course or repeated courses — cumulative exposure is associated with reduced birth weight and head circumference and possible neurodevelopmental effects.','Maternal hyperglycaemia (monitor and treat, especially in diabetes — insulin requirements rise for 24–72 h), pulmonary oedema (esp. with β-agonist tocolysis and multiple pregnancy), leucocytosis, and infection.','Complete the course even if delivery seems imminent — partial benefit still accrues.','Do not use in chorioamnionitis without antibiotic cover and delivery planning.','Betamethasone is preferred over dexamethasone (better evidence for IVH reduction); use dexamethasone when betamethasone is unavailable.','Late preterm steroids (34–36⁺⁶ weeks, ALPS trial): betamethasone 12 mg IM × 2 doses if delivery is expected within 7 days and no prior course was given — but neonatal hypoglycaemia is more common.'],
  ref:['WHO-ACS','ACOG-ACS','NICE-NG25','ALPS','FOGSI'] });

R({ id:'labetalol-obs', n:'Labetalol — severe hypertension in pregnancy', sys:'obs', cls:'Combined α1 + β blocker',
  ind:'Severe hypertension in pregnancy/pre-eclampsia/eclampsia (SBP ≥160 or DBP ≥110 mmHg) — target <160/105 and ideally 130–150/80–100', pop:'adult', risk:4,
  d:{t:'mg', lo:20, hi:80, cap:220, rep:'20 mg IV over 2 min; if BP is not controlled after 10 min give 40 mg, then 80 mg every 10 min; maximum cumulative 220 mg'},
  fx:[{s:'5 mg/mL', c:5, u:'mg', p:'10 mL ampoule (50 mg) — availability variable in India', b:'Labetalol IP — Neon/Intas; Labeta, Trandate (import)', r:'IV/PO', hl:1},
      {s:'100 mg / 200 mg tablets', c:100, u:'mg', p:'strip of 10', b:'Labetalol 100/200 mg tablets', r:'PO'}],
  admin:'20 mg IV over 2 min; if the target BP is not reached in 10 min, give 40 mg; then 80 mg every 10 min to a maximum of 220 mg cumulatively. Maintenance infusion 1–2 mg/min (or 50–150 mg/h) if required. Oral maintenance 100–200 mg BD–TDS. ALTERNATIVES where IV labetalol is unavailable: nifedipine 10 mg PO (repeat after 30 min) or hydralazine 5–10 mg IV.',
  dil:'May be given undiluted or diluted in NS/D5W to 1 mg/mL.',
  warn:['Avoid in asthma, heart failure, bradycardia (<50/min), and heart block.','Maternal hypotension reduces placental perfusion — lower the BP gradually and monitor the fetal heart rate.','Fetal bradycardia and neonatal hypoglycaemia/bradycardia after delivery — monitor the neonate.','Do NOT reduce the BP below 130/80 — placental perfusion is pressure-dependent.','Hydralazine causes more maternal hypotension and caesarean delivery; nifedipine is a good oral alternative.','Magnesium sulfate is NOT an antihypertensive — give it separately for seizure prophylaxis.'],
  ref:['ACOG-HTN-PREG','NICE-NG133','FOGSI','WHO-PREECLAMPSIA','BNF'] });

/* ================= NEONATAL ICU ================= */
R({ id:'neonatal-adrenaline', n:'Adrenaline — neonatal resuscitation', sys:'neonatal', cls:'Non-selective adrenergic agonist',
  ind:'Neonatal resuscitation when the heart rate remains <60/min despite 30 s of effective ventilation (preferably via an ETT) with 100% oxygen and chest compressions', pop:'neo', maxAge:0.08, risk:5,
  d:{t:'mcgkg', lo:10, hi:30, cap:100, rep:'10–30 mcg/kg IV/IO (0.01–0.03 mg/kg) every 3–5 min; via the ETT use 50–100 mcg/kg (0.05–0.1 mg/kg)'},
  fx:[{s:'1 mg/mL (1:1000)', c:1, u:'mg', p:'1 mL ampoule — dilute to 0.1 mg/mL (1:10,000) before use', b:'Adrenaline IP — Neon, Vins, BDH', r:'IV/IO/ETT', hl:1}],
  admin:'IV/IO via an umbilical venous catheter is the preferred route: 0.01–0.03 mg/kg (0.1–0.3 mL/kg of 1:1000, or 0.1–0.3 mL/kg of 1:10,000), flush with 0.5–1 mL of NS. ETT route (if no vascular access): 0.05–0.1 mg/kg of 1:1000 diluted to 1–2 mL with NS.',
  dil:'Prepare 1:10,000 by adding 0.1 mL of 1:1000 to 0.9 mL of NS in a 1 mL syringe.',
  warn:['VENTILATION IS THE KEY — most neonatal bradycardia is hypoxic, and adrenaline is ineffective until the lungs are aerated. Correct tube position, seal and chest movement first.','Use the 1:1000 ampoule directly only if you are certain of the volume; label every syringe with the concentration and route.','Hypovolaemia (placental abruption, fetomaternal haemorrhage, twin-twin transfusion) needs volume: 10 mL/kg of 0.9% NaCl or O-negative blood over 5–10 min.','Naloxone is NOT part of neonatal resuscitation and is contraindicated in infants of opioid-dependent mothers (seizures).','Consider withholding resuscitation at ≥20 min of no detectable heart rate despite optimal care.'],
  ref:['NRP2025','AHA2025-PALS','IAP-NRP','ERC2025-NEO','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','PG-TB-PED','IAP-STG'] });

R({ id:'surfactant', n:'Pulmonary surfactant', sys:'neonatal', cls:'Exogenous surfactant (phospholipid + protein)',
  ind:'Respiratory distress syndrome in preterm neonates — early rescue (intubated) or prophylactic; also less-invasive surfactant administration (LISA/MIST)', pop:'neo', maxAge:0.1, risk:4,
  d:{t:'mgkg', v:200, cap:1000, rep:'poractant alfa 200 mg/kg (superior); beractant 100 mg/kg; up to 3–4 repeat doses if FiO₂ remains >0.3–0.4'},
  fx:[{s:'80 mg/mL poractant alfa (porcine)', c:80, u:'mg', p:'1.5 mL vial (120 mg) and 3 mL vial (240 mg)', b:'Curosurf (Chiesi), Neosurf (Neon), Surfactant-T', r:'ETT', hl:1, own:{kg:200,u:'mg',l:'PORACTANT ALFA 200 mg/kg = 2.5 mL/kg — a single larger dose is superior to 100 mg/kg with fewer repeat doses.'}},
      {s:'25 mg/mL beractant (bovine)', c:25, u:'mg', p:'4 mL vial (100 mg), 8 mL vial (200 mg)', b:'Survanta (Abbott), Infasurf (alternative)', r:'ETT', own:{kg:100,u:'mg',l:'BERACTANT 100 mg/kg = 4 mL/kg.'}},
      {s:'35 mg/mL bovine surfactant (Indian)', c:35, u:'mg', p:'3 mL vial (105 mg)', b:'Neosurf (Neon), Surfactant-BL', r:'ETT', own:{kg:100,u:'mg',l:'Bovine surfactant 100 mg/kg = 2.9 mL/kg (Indian-manufactured bovine surfactant).'}}],
  admin:'PORACTANT ALFA: 200 mg/kg = 2.5 mL/kg (a single larger dose is superior to 100 mg/kg with fewer repeat doses). BERACTANT: 100 mg/kg = 4 mL/kg. Warm to room temperature (do not shake, do not use an artificial warmer), draw up, and instil down the ETT in 2–4 aliquots with the head midline and then turned 45° left/right, each followed by 5–10 manual breaths. Repeat doses if FiO₂ >0.3–0.4 or mean airway pressure rises (up to 3 further doses at 8–12 h intervals).',
  dil:'Ready to use — DO NOT dilute and DO NOT shake (foaming causes under-dosing).',
  warn:['Transient bradycardia, desaturation, airway obstruction and reflux of surfactant into the ETT during instillation — pause and ventilate with 100% oxygen until the heart rate recovers.','Pulmonary haemorrhage with very preterm infants and a patent ductus arteriosus.','Do not administer through a laryngeal mask in very small infants.','Use within 8 h of opening; discard the remainder of a single-dose vial.','LISA/MIST (less-invasive surfactant administration via a thin catheter on spontaneous CPAP breathing) reduces the need for mechanical ventilation — preferred where the skill exists.','Ensure the ETT is correctly positioned and patent before instillation.'],
  ref:['NRP2025','EURO-RDS','IAP-NICU','AAP-RDS','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','PG-TB-PED','IAP-STG'] });

R({ id:'caffeine-apnoea', n:'Caffeine citrate', sys:'neonatal', cls:'Methylxanthine — adenosine-receptor antagonist and respiratory stimulant',
  ind:'Apnoea of prematurity; facilitation of extubation; prevention of BPD', pop:'neo', maxAge:0.5, risk:3,
  d:{t:'mgkg', lo:10, hi:20, capDayKg:20, rep:'LOADING 20 mg/kg of caffeine CITRATE (= 10 mg/kg caffeine base) IV over 30 min, then 5–10 mg/kg/day of the citrate (= 2.5–5 mg/kg/day of the base) once daily'},
  fx:[{s:'20 mg/mL caffeine citrate (= 10 mg/mL caffeine base)', c:20, u:'mg', multi:1, p:'1 mL ampoule (20 mg citrate), 3 mL ampoule', b:'Caffneon (Neon), Caficita (Cipla), Caffeine Citrate IP — Intas/Samarth; Cafcit', r:'IV/PO', hl:1}],
  admin:'Loading 20 mg/kg of the CITRATE (10 mg/kg of the base) IV over 30 min, then maintenance 5–10 mg/kg/day of the citrate once daily, IV or PO. Increase to 10 mg/kg/day of the citrate if apnoea persists. Continue until 32–34 weeks corrected gestation and apnoea-free for 5–7 days.',
  dil:'Ready to use; may be diluted in NS, D5W or sterile water. Do NOT confuse caffeine citrate with caffeine base — the citrate is twice the weight of the base.',
  warn:['CITRATE vs BASE CONFUSION is a classic neonatal medication error — always prescribe and check in terms of the CITRATE.','Tachycardia (>180/min), feeding intolerance, hyperglycaemia, jitteriness, diuresis, hypokalaemia.','Reduce or hold if the heart rate exceeds 180–200/min or if significant reflux/feeding intolerance develops.','Caffeine is superior to aminophylline/theophylline (fewer side effects, no level monitoring, once-daily dosing) — it is the drug of choice for apnoea of prematurity.','Monitor for necrotising enterocolitis (no clear increased risk) and ROP (no increased risk).'],
  ref:['CAP-TRIAL','NRP2025','IAP-NICU','BNFC','EURO-RDS','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','PG-TB-PED','IAP-STG'] });

R({ id:'pge1-ductus', n:'Alprostadil (Prostaglandin E1)', sys:'neonatal', cls:'Vasodilator prostaglandin — maintains ductal patency',
  ind:'Duct-dependent congenital heart disease (duct-dependent systemic or pulmonary circulation) until surgical/interventional correction; transposition of the great arteries, coarctation/aortic interruption, pulmonary atresia, critical PS, HLHS', pop:'neo', maxAge:0.2, risk:5, inf:true,
  d:{t:'mcgkgmin', lo:0.01, hi:0.1},
  diln:[{l:'500 mcg in 50 mL D5W → 10 mcg/mL (0.05 mcg/kg/min in a 3-kg neonate = 0.9 mL/h)', amt:500, in:50, u:'mcg', bag:'50 mL 5% dextrose'},
        {l:'500 mcg in 25 mL D5W → 20 mcg/mL (fluid-restricted neonate)', amt:500, in:25, u:'mcg', bag:'25 mL 5% dextrose'}],
  fx:[{s:'500 mcg/mL', c:500, u:'mcg', p:'1 mL ampoule (500 mcg)', b:'Alprostadil IP — Neon (Elshitan), Intas; Prostin VR Pediatric (Pfizer), PGE1, Alpostin', r:'IV', hl:1}],
  admin:'Start 0.05–0.1 mcg/kg/min IV through a secure line (umbilical arterial/venous or a reliable peripheral line); once the ductus opens and the circulation stabilises, reduce to the lowest effective dose (often 0.01–0.025 mcg/kg/min). Use a syringe pump with a dedicated line.',
  dil:'Dilute in D5W or NS; protect from light; use within 24 h.',
  warn:['APNOEA occurs in ~10–12% of neonates (dose-related, more common above 0.1 mcg/kg/min and in low-birth-weight infants) — be prepared to intubate; have the airway equipment at the cot side.','Flushing, fever, hypotension, tachycardia, diarrhoea, irritability, seizure-like activity.','Cortical hyperostosis with prolonged infusion (>4 weeks) — use the lowest effective dose.','Never interrupt the infusion during transfer — carry a spare syringe and batteries; an interruption can be fatal.','Extravasation is dangerous — a central line is preferred.','Echocardiographic confirmation of the anatomy is essential; some lesions (e.g. total anomalous pulmonary venous drainage with obstruction) may worsen with ductal patency.'],
  ref:['NRP2025','AHA2025-PALS','IAP-NICU','BNFC','PEDIATRIC-CARDIOLOGY','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','PG-TB-PED','IAP-STG'] });

R({ id:'neonatal-hypoglycaemia', n:'Neonatal hypoglycaemia — dextrose', sys:'neonatal', cls:'Carbohydrate replacement',
  ind:'Neonatal glucose <47 mg/dL (2.6 mmol/L) — symptomatic, or <40 mg/dL asymptomatic in the first 48 h', pop:'neo', maxAge:0.5, risk:4,
  d:{t:'mgkg', lo:200, hi:200, capDay:2000, rep:'2 mL/kg of 10% dextrose IV (= 200 mg/kg glucose), then a continuous infusion at a glucose infusion rate of 6–8 mg/kg/min'},
  fx:[{s:'10% dextrose (100 mg/mL)', c:100, u:'mg', p:'100 mL / 500 mL bag; 10 mL ampoule (1 g)', b:'Dextrose 10% IP — Claris, Eurolife, Neon', r:'IV', hl:1},
      {s:'25% dextrose (250 mg/mL)', c:250, u:'mg', p:'10 mL ampoule — DILUTE before neonatal use', b:'Dextrose 25% IP — Neon, Samarth', r:'IV', own:{text:'NEVER give 25% or 50% dextrose undiluted to a newborn — the osmolar load causes rebound hypoglycaemia, hyperosmolality and intraventricular haemorrhage. Use 25% ONLY diluted to 10% and via a CENTRAL line when a higher glucose infusion rate is needed within a fluid limit.'}},
      {s:'5% dextrose', c:50, u:'mg', p:'100 mL bag', b:'Dextrose 5% IP', r:'IV', own:{text:'5% dextrose is too dilute for neonatal hypoglycaemia — it delivers only 50 mg/mL of glucose, so the fluid volume needed to reach a GIR of 6–8 mg/kg/min causes fluid overload. Use 10% dextrose.'}}],
  admin:'Bolus 2 mL/kg of 10% dextrose (200 mg/kg of glucose) IV over 1–2 min, then start a continuous infusion of 10% dextrose at a glucose infusion rate (GIR) of 6–8 mg/kg/min: rate (mL/h) = GIR × weight (kg) × 60 ÷ 100 for D10. Recheck the glucose after 30 min and escalate the GIR by 2 mg/kg/min up to a maximum of 12 mg/kg/min (use 25% dextrose via a central line if a higher GIR is needed to limit fluid).',
  dil:'NEVER give 25% or 50% dextrose undiluted to a neonate — always use 10% peripherally (25% only through a central line).',
  warn:['Hypertonic dextrose causes rebound hyperinsulinaemia, rebound hypoglycaemia, phlebitis, extravasation injury and (in preterm infants) intraventricular haemorrhage.','Persistent hypoglycaemia despite a GIR of 12 mg/kg/min: consider hyperinsulinaemic hypoglycaemia (glucagon 30 mcg/kg IM/SC or 0.01–0.03 mg/kg/h infusion; diazoxide 5–15 mg/kg/day; octreotide 5–20 mcg/kg/day), sepsis, inborn errors of metabolism, hypopituitarism or adrenal insufficiency (hydrocortisone 5 mg/kg IV).','Feed enterally as soon as it is safe — enteral feeds are the best maintenance.','Screen and treat infants of diabetic mothers, SGA/LGA babies, preterms, and those with sepsis or perinatal asphyxia.'],
  ref:['AAP-NEO-GLUCOSE','IAP-NEO-HYPO','WHO-NEO','BNFC','PES-NEO','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','PG-TB-PED','IAP-STG'] });

R({ id:'neonatal-sepsis', n:'Neonatal sepsis — empirical antibiotics', sys:'neonatal', cls:'β-lactam + aminoglycoside combination',
  ind:'Early-onset (<72 h) and late-onset neonatal sepsis, meningitis and pneumonia — start within 1 h of suspicion after cultures', pop:'neo', maxAge:0.5, risk:5,
  d:{t:'mgkg', lo:50, hi:50, capDay:300, rep:'ampicillin 50 mg/kg IV q12h (<7 days) or q8h (>7 days) PLUS gentamicin 4–5 mg/kg IV/IM once daily'},
  fx:[{s:'500 mg ampicillin vial', c:100, u:'mg', p:'500 mg vial reconstituted with 5 mL WFI → 100 mg/mL', b:'Ampicillin IP — Neon, Abbott, Saraca; Principen, Ampilin', r:'IV/IM', hl:1, prep:'Reconstitute 500 mg with 5 mL sterile WFI → 100 mg/mL; use within 1 h'},
      {s:'40 mg/mL gentamicin', c:40, u:'mg', p:'1 mL ampoule (40 mg), 2 mL ampoule (80 mg)', b:'Gentamicin IP — Samarth, Neon, Claris; Genticyn', r:'IV/IM', own:{kgLo:4,kgHi:5,u:'mg',l:'GENTAMICIN 4–5 mg/kg IV/IM ONCE DAILY (q36–48 h if <1200 g or <7 days old). Monitor levels/trough and urine output.'}},
      {s:'10 mg/mL gentamicin (paediatric)', c:10, u:'mg', p:'2 mL ampoule (20 mg)', b:'Gentamicin 10 mg/mL', r:'IV/IM', own:{kgLo:4,kgHi:5,u:'mg',l:'GENTAMICIN 4–5 mg/kg IV/IM once daily — the 10 mg/mL paediatric strength avoids drawing tiny volumes and reduces measurement error.'}},
      {s:'1 g cefotaxime vial', c:100, u:'mg', p:'1 g vial reconstituted with 10 mL WFI → 100 mg/mL', b:'Cefotax (Neon), Taxim (Sanofi), Otocef', r:'IV/IM', own:{kg:50,u:'mg',l:'CEFOTAXIME 50 mg/kg IV q8h — add for meningitis, or use with ampicillin for early-onset sepsis. Use cefotaxime, NOT ceftriaxone, in neonates.'}}],
  admin:'EARLY-ONSET SEPSIS: ampicillin 50 mg/kg IV q12h (if <7 days old or birth weight <1200 g) or q8h (if >7 days) PLUS gentamicin 4–5 mg/kg IV/IM once daily (q36–48 h if <1200 g or <7 days). LATE-ONSET or hospital-acquired (or if staphylococcal infection is suspected): cloxacillin/flucloxacillin 50 mg/kg q6–8h PLUS amikacin 15 mg/kg once daily, or vancomycin 15 mg/kg q12h (q8h if >7 days) PLUS amikacin. MENINGITIS: ampicillin 100 mg/kg q8h PLUS cefotaxime 50 mg/kg q8h PLUS gentamicin (or vancomycin + ceftazidime for late-onset).',
  dil:'Reconstitute and dilute in 5–10 mL of NS/D5W; infuse over 30 min (gentamicin over 30–60 min).',
  warn:['Take blood, urine and CSF cultures BEFORE the first dose — but never delay antibiotics beyond 1 hour in a sick neonate.','NEVER use ceftriaxone in neonates (bilirubin displacement, calcium precipitation) — cefotaxime is the cephalosporin of choice.','Monitor gentamicin/amikacin trough levels and creatinine; the dosing interval depends on gestational and postnatal age.','Ampicillin + gentamicin does not cover Staphylococcus aureus — add cloxacillin or vancomycin if there are risk factors (lines, prematurity, skin sepsis, mastitis in the mother).','Stop antibiotics at 48–72 h if cultures are negative and the infant is well — antibiotic overuse drives resistance and increases NEC, candidiasis and mortality.','Supportive care (thermoregulation, fluids, inotropes, respiratory support, glucose) is equally important.','Consider antifungal prophylaxis in extremely low birth weight infants.'],
  ref:['IAP-NEO-SEPSIS','WHO-NEO','NRP2025','NICE-NG195','SANFORD','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','PG-TB-PED','IAP-STG'] });

/* ================= PAEDIATRIC PROGRAMMES ================= */
R({ id:'ibuprofen-pda', n:'Ibuprofen — patent ductus arteriosus (PDA)', sys:'neonatal', cls:'Non-selective COX inhibitor (prostaglandin synthesis blocker)',
  ind:'Haemodynamically significant patent ductus arteriosus in preterm infants (first-line medical closure); also used in term infants awaiting intervention', pop:'neo', risk:4, inf:false,
  d:{t:'mgkg', lo:5, hi:10, cap:20, rep:'STANDARD course: 10 mg/kg, then 5 mg/kg at 24 h and 5 mg/kg at 48 h (three doses). If treatment starts AFTER 72 h of life, units using the HIGHER course give 20 mg/kg, then 10 mg/kg at 24 h and 10 mg/kg at 48 h. A second course may be given if the duct remains significant.'},
  fx:[{s:'5 mg/mL ibuprofen (Pedea, IV)', c:5, u:'mg', p:'2 mL ampoule (10 mg)', b:'Pedea (Orphan Europe); generic ibuprofen IV where licensed', r:'IV', hl:1},
      {s:'100 mg/5 mL oral suspension', c:20, u:'mg', p:'100 mL bottle', b:'Ibugesic Plus drops (Cipla), Brufen syrup (Abbott)', r:'PO'}],
  admin:'IV: give over 15 minutes through a secure line. ORAL: give with feeds (preferred where the baby is on full enteral feeds — enteral ibuprofen closes the duct at least as well as IV). Reassess the duct and the shunt 24–48 h after the third dose.',
  dil:'No dilution — the 5 mg/mL IV preparation is ready to use. Flush the line; ibuprofen is incompatible with several drugs in a Y-site (check locally).',
  warn:['CONTRAINDICATED or use with great caution in: thrombocytopenia, bleeding tendency or IVH, oliguria (urine <1 mL/kg/h), serum creatinine >1.6 mg/dL, NEC, recent intraventricular haemorrhage, and life-threatening infection.',
        'REDUCES CEREBRAL, MESENTERIC AND RENAL PERFUSION — monitor urine output and creatinine; stop if oliguria develops.',
        'Doses are always of IBUPROFEN (not of the salt) — check the vial label, and do not confuse with the oral antipyretic syrup strengths.',
        'Do not run concurrently with other prostaglandin inhibitors (indomethacin/paracetamol courses) without a definite plan.'],
  notes:['Roughly 70–80 % of ducts close after one course. The dose is the same by the IV and oral routes, but the oral route is only for babies tolerating enteral feeds.'],
  ref:['HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','IAP-STG','NELSON']});
R({ id:'indomethacin-pda', n:'Indomethacin — patent ductus arteriosus (PDA)', sys:'neonatal', cls:'Non-selective COX inhibitor (prostaglandin synthesis blocker)',
  ind:'Haemodynamically significant PDA where ibuprofen is unavailable, contraindicated or has failed', pop:'neo', risk:4,
  d:{t:'mgkg', lo:0.1, hi:0.2, rep:'INITIAL dose 0.2 mg/kg IV over 30 min, then TWO further doses at 12–24 h intervals. Maintenance dose by postnatal age: <48 h old or weight <1 kg = 0.1 mg/kg; 2–7 days old = 0.2 mg/kg; >7 days old = 0.25 mg/kg.'},
  fx:[{s:'1 mg lyophilised powder (indomethacin sodium trihydrate)', c:1, u:'mg', p:'1 mg vial — reconstitute with 1 mL of the supplied diluent or WFI → 1 mg/mL', b:'Indocid (imported/restricted supply); indomethacin injection IP where stocked', r:'IV', hl:1}],
  admin:'IV over 30 minutes (never a bolus). The 1 mg vial reconstituted to 1 mL gives 1 mg/mL; for a 1 kg baby the 0.2 mg/kg dose is 0.2 mL — use a 1 mL syringe.',
  dil:'Reconstitute with the diluent supplied (contains no preservative). Discard any unused reconstituted solution. Slight yellow discolouration is normal; discard if the solution is discoloured on standing.',
  warn:['The dose is by POSTNATAL AGE — the same drug at 0.25 mg/kg in a 2-day-old would be an overdose.',
        'Renal and mesenteric vasoconstriction: watch urine output, creatinine, sodium and feeds. Stop for oliguria.',
        'Same contraindications as ibuprofen: thrombocytopenia, bleeding, IVH, NEC, oliguria, high creatinine.',
        'Never give with another prostaglandin inhibitor in the same course.'],
  notes:['Indomethacin exposes the neonate to a lower fluid load than ibuprofen (it is drawn from a 1 mg vial) — useful in the fluid-restricted baby — but it constricts renal and mesenteric vessels more.'],
  ref:['HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON']});
R({ id:'vitamin-k-prophylaxis', n:'Vitamin K1 (phytomenadione) — newborn prophylaxis', sys:'neonatal', cls:'Vitamin K analogue (fat-soluble cofactor for clotting factors II, VII, IX, X)',
  ind:'PREVENTION of vitamin K deficiency bleeding (VKDB) — given to EVERY newborn within 6 hours of birth, term or preterm', pop:'neo', risk:4,
  d:{t:'text', text:'FIXED dose by birth weight, NOT per kg: 0.5 mg IM if birth weight is 1500 g or less; 1 mg IM if birth weight is more than 1500 g. Give within 6 hours of birth.', rep:'A single IM dose at birth. Preterm infants on prolonged parenteral nutrition, or with cholestasis, may need further doses per unit protocol.'},
  fx:[{s:'10 mg/mL phytomenadione (Konakion MM paediatric)', c:10, u:'mg', p:'0.2 mL ampoule (2 mg) — the only strength that should be used in neonates', b:'Konakion MM Paediatric (Roche); phytomenadione injection IP (Vibiz, Neptune)', r:'IM', hl:1, use:'fixed',
       give:'1500 g or less: 0.05 mL (0.5 mg). More than 1500 g: 0.1 mL (1 mg). Give IM into the anterolateral thigh within 6 hours of birth.'},
      {s:'1 mg/mL phytomenadione (adult strength)', c:1, u:'mg', p:'1 mL ampoule (1 mg)', b:'Vitamin K injection IP — various', r:'IM', use:'fixed',
       give:'DO NOT USE IN NEONATES — the adult 1 mg/mL strength is too dilute to inject in the small volume required and invites a 10-fold error. Use the 10 mg/mL paediatric ampoule.'}],
  admin:'IM into the anterolateral thigh, within 6 hours of birth, after initial stabilisation. An oral regimen (2 mg at birth, repeated at 2–4 and 6–8 weeks) exists only for parents who decline the injection and is less effective — it is NOT the default.',
  dil:'None. The 2 mg/0.2 mL paediatric ampoule is used as supplied; do not dilute.',
  warn:['THE STRENGTH MATTERS: Konakion MM Paediatric is 10 mg/mL (2 mg in 0.2 mL). Adult vitamin K is 1 mg/mL — using it for a newborn means measuring 0.05–0.1 mL, a classic 10-fold error. Stock only the paediatric ampoule in the nursery.',
        'Given IM only. IV phytomenadione carries an anaphylactoid risk and is reserved for serious bleeding.',
        'Protect the ampoule from light until the moment of injection.'],
  notes:['VKDB now occurs almost exclusively in babies who did not receive prophylaxis: the early form in the first week, the classic form at 2–7 days, and the late form at 2–12 weeks with a risk of intracranial haemorrhage.'],
  ref:['HARRIET-LANE','NELSON','IAP-STG','SINGH-DOSES']});

R({ id:'ivig-kawasaki', n:'Intravenous immunoglobulin (IVIG) — Kawasaki disease', sys:'misc', cls:'Pooled human immunoglobulin G (immunomodulatory)',
  ind:'Kawasaki disease within the first 10 days of fever (reduces coronary aneurysms from ~25% to ~4%); also immune thrombocytopenia, Guillain–Barré syndrome, toxic shock, myocarditis', pop:'paed', risk:4,
  d:{t:'gkg', lo:0.4, hi:2, capDay:150, rep:'Kawasaki: 2 g/kg as a single infusion over 10–12 h PLUS aspirin; ITP: 1 g/kg × 1–2 days or 0.4 g/kg × 5 days; GBS: 0.4 g/kg/day × 5 days (total 2 g/kg)'},
  fx:[{s:'5% (50 mg/mL) IVIG', c:50, u:'mg', p:'50 mL (2.5 g), 100 mL (5 g), 200 mL (10 g) bottles', b:'Igven (Reliance Life Sciences), Flebogamma (Grifols), Gammagard (Baxter/BPL), Human Normal Immunoglobulin IP — CSL/Kedrion', r:'IV', hl:1},
      {s:'10% (100 mg/mL) IVIG', c:100, u:'mg', p:'25 mL (2.5 g), 50 mL (5 g), 100 mL (10 g), 200 mL (20 g)', b:'Igven 10%, Flebogamma 10%, Privigen, Gammagard 10%', r:'IV'}],
  admin:'Kawasaki disease: 2 g/kg IV as a single infusion over 10–12 h within 10 days of fever onset, PLUS aspirin 30–50 mg/kg/day (India/low-dose regimens use 3–5 mg/kg/day in the acute phase) in divided doses until afebrile for 48 h, then 3–5 mg/kg once daily for 6–8 weeks (or until the coronary arteries are normal). Start the infusion at 0.5–1 mL/kg/h and increase every 15–30 min as tolerated.',
  dil:'Ready to use; do not shake; use an in-line filter if supplied; do not mix with other drugs or fluids.',
  warn:['Infusion reactions (fever, chills, flushing, hypotension, back pain) in 1–5% — slow or stop the infusion, give paracetamol and an antihistamine, then restart at a lower rate.','Aseptic meningitis, acute kidney injury (sucrose-containing products), thrombosis, TRALI, haemolysis (anti-A/anti-B).','Anaphylaxis in IgA-deficient patients.','Live vaccines (MMR, varicella) must be deferred for 11 months after a 2 g/kg dose.','10–20% of Kawasaki patients are IVIG-resistant — give a second 2 g/kg dose, or corticosteroids (methylprednisolone 30 mg/kg × 1–3 days) or infliximab.','Echocardiography at diagnosis, at 2 weeks and at 6–8 weeks (and more often if abnormalities).','Aspirin is used despite the theoretical Reye risk — the benefit clearly outweighs it in Kawasaki disease.'],
  ref:['AHA-KAWASAKI','IAP-KAWASAKI','BNFC','ISCCM-PEDS','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','IAP-STG'] });

R({ id:'zinc-ors-diarrhoea', n:'Zinc + ORS — acute paediatric diarrhoea', sys:'misc', cls:'Micronutrient supplement + oral rehydration salts',
  ind:'Acute diarrhoea in children <5 years — reduces the duration and severity of the episode and prevents further episodes for 2–3 months (WHO/UNICEF; India national programme)', pop:'paed', maxAge:5, risk:1,
  d:{t:'mg', lo:10, hi:20, rep:'<6 months: 10 mg (½ tablet/2.5 mL syrup) daily × 14 days; ≥6 months: 20 mg (1 tablet/5 mL syrup) daily × 14 days — complete the full 14-day course even after diarrhoea stops'},
  fx:[{s:'20 mg dispersible tablet', c:20, u:'mg', p:'strip of 10', b:'Z&D (Torrent), Zincovit dispersible, Zifin, Zinconia 20', r:'PO', hl:1},
      {s:'20 mg/5 mL syrup', c:4, u:'mg', p:'100 mL bottle', b:'Z&D syrup, Zincovit syrup, Zincofer syrup', r:'PO'},
      {s:'WHO low-osmolarity ORS sachet (20.5 g in 1 L; Na⁺ 75 mmol/L, glucose 75 mmol/L, osmolarity 245 mOsm/L)', c:1, u:'ml', p:'sachet for 1 litre of water', b:'Electral (FDC), Oralyte, WHO-ORS, Rehydralyte, O-RS', r:'PO', use:'fixed', give:'Plan A (no dehydration): <2 years 50-100 mL after each loose stool; ≥2 years 100-200 mL; adults as much as wanted. Plan B (some dehydration): 75 mL/kg over 4 h, then reassess. Plan C (severe dehydration): IV Ringer lactate 100 mL/kg (30 mL/kg in the first hour for infants <12 months, then 70 mL/kg over 5 h; 100 mL/kg over 3 h for older children).'}],
  admin:'Zinc 20 mg PO daily × 14 days (10 mg if <6 months) — dissolve the dispersible tablet in a small amount of breast milk, ORS or clean water. ORS: Plan A (no dehydration) 50–100 mL after each loose stool; Plan B (some dehydration) 75 mL/kg over 4 h; Plan C (severe dehydration) IV RL 100 mL/kg (30 mL/kg over 1 h then 70 mL/kg over 5 h in infants <12 months; 30 mL/kg over 30 min then 70 mL/kg over 2.5 h in children ≥12 months).',
  dil:'ORS must be mixed in exactly 1 litre (or 200 mL for the small sachet) of safe water — an incorrect concentration is dangerous.',
  warn:['Do NOT give antibiotics routinely for acute watery diarrhoea — they are indicated only for dysentery (bloody diarrhoea), suspected cholera with severe dehydration, or specific pathogens.','Zinc causes vomiting if given on an empty stomach in a large dose — give after a feed.','Continue breastfeeding and feeding throughout — never starve a child with diarrhoea.','Avoid anti-motility drugs (loperamide) in children — they cause ileus, sedation and death.','Severe dehydration requires IV fluids; ORS alone is inadequate for shock.','Look for and treat coexisting pneumonia, malaria, measles, severe malnutrition and UTI.','Vitamin A supplementation is indicated in measles and severe malnutrition.'],
  ref:['WHO-DIARRHOEA','IAP-DIARRHOEA','UNICEF-ZINC','NVBDCP-IDCF','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','IAP-STG'] });

R({ id:'vitamin-a-measles', n:'Vitamin A — measles and severe malnutrition', sys:'misc', cls:'Fat-soluble retinoid',
  ind:'Measles (all children), severe acute malnutrition, xerophthalmia, vitamin A deficiency', pop:'paed', risk:2,
  d:{t:'units', lo:50000, hi:200000, capDay:200000, rep:'age-banded single dose on day 1 and day 2 (and again at 2–4 weeks if there are signs of vitamin A deficiency)'},
  fx:[{s:'100,000 IU/mL oral solution / 100,000 IU capsule', c:100000, u:'units', p:'1 mL spoon/capsule; 200,000 IU capsule', b:'Aquasol A (USV), Vitamin A capsules (UNICEF/NVBDCP supply), Retinol palmitate, A to Z drops', r:'PO/IM', hl:1},
      {s:'100,000 IU/mL injectable (water-miscible)', c:100000, u:'units', p:'1 mL ampoule', b:'Aquasol A injection (USV), Vitamin A injection', r:'IM'}],
  admin:'MEASLES (give on day 1 and again on day 2, and a third dose at 2–4 weeks if there are eye signs): <6 months 50,000 IU; 6–11 months 100,000 IU; ≥12 months 200,000 IU. SEVERE ACUTE MALNUTRATION on admission: the same age-banded single dose. Xerophthalmia: the same dose on day 1, day 2 and at 2 weeks.',
  dil:'Oral administration is preferred; the capsule can be snipped and the contents squeezed into the mouth. Use the IM preparation only if oral administration is impossible (e.g. severe vomiting, malabsorption).',
  warn:['ACUTE TOXICITY: vomiting, headache, papilloedema, bulging fontanelle, irritability, peeling skin — the recommended 2-dose schedule is safe.','Chronic excess causes hepatotoxicity, bone pain and hypercalcaemia.','Do not give high-dose vitamin A in pregnancy (teratogenic).','Vitamin A reduces measles mortality by ~50% and blindness — it is one of the highest-yield interventions in Indian paediatrics.','Give with food (fat-soluble).'],
  ref:['WHO-MEASLES','IAP-MEASLES','WHO-SAM','NVBDCP-MEASLES','BNFC','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','IAP-STG'] });

R({ id:'benzathine-penicillin-rhd', n:'Benzathine benzylpenicillin — rheumatic fever prophylaxis', sys:'misc', cls:'Long-acting depot penicillin (IM ONLY)',
  ind:'Primary prophylaxis of rheumatic fever after streptococcal pharyngitis; SECONDARY prophylaxis after acute rheumatic fever/rheumatic heart disease (the main burden in India)', pop:'all', risk:4,
  d:{t:'units', lo:600000, hi:1200000, rep:'≤27 kg: 600,000 IU IM every 3–4 weeks; >27 kg: 1,200,000 IU IM every 3–4 weeks (every 3 weeks in high-risk patients and in India\'s endemic setting)'},
  fx:[{s:'600,000 IU vial', c:300000, u:'units', p:'vial reconstituted with 2 mL WFI → 300,000 IU/mL; deep IM only', b:'Penidure 6 (Abbott), Benzathine Penicillin G IP — Neon/Samarth; Bicillin L-A', r:'IM', hl:1, prep:'Reconstitute with 2 mL sterile WFI, shake well to form a uniform suspension, and inject DEEP IM into the upper outer quadrant of the gluteus (never IV, never SC)'},
      {s:'1,200,000 IU vial', c:300000, u:'units', p:'vial reconstituted with 4 mL WFI → 300,000 IU/mL', b:'Penidure 12 (Abbott), Benzathine Penicillin 1.2 MIU', r:'IM', prep:'Reconstitute with 4 mL sterile WFI, shake well, inject deep IM'}],
  admin:'Reconstitute, shake well and inject DEEP IM into the upper outer quadrant of the buttock using a long needle (aspirate first). Alternate sides each visit. Duration of secondary prophylaxis: rheumatic fever without carditis — 5 years or until 21 years (whichever is longer); with carditis but no residual valve disease — 10 years or until 21 years; with residual valve disease — 10 years or until 40 years (sometimes lifelong).',
  dil:'Reconstitute with sterile WFI to a uniform milky suspension; do not use if the suspension separates or contains large particles (needle blockage).',
  warn:['INTRAVENOUS ADMINISTRATION IS FATAL — cardiorespiratory arrest (Hoigne syndrome is a non-allergic pseudo-anaphylactic reaction with fear, hallucinations and seizures after inadvertent intravascular injection). Aspirate before injecting and inject slowly.','Anaphylaxis — have adrenaline 1:1000 drawn up; observe the patient for 30 min after every injection.','Pain at the injection site is the main reason for poor adherence — explain the importance, warm the syringe to body temperature, inject slowly and use a lidocaine-warming technique where local practice allows.','Adherence is the critical determinant of outcome — maintain a patient register, give an appointment card and recall defaulters.','Never confuse benzathine penicillin with benzylpenicillin (Penicillin G, IV) or procaine penicillin (IM).','Procaine/benzathine penicillin are different salts with different routes and durations.'],
  ref:['AHA-RHD','WHO-RHD','IAP-RHD','NCD-RHD-INDIA','BNF','IAP-STG','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'bronchiolitis', n:'Bronchiolitis — supportive care (what NOT to give)', sys:'respiratory', cls:'Supportive respiratory care',
  ind:'Acute viral bronchiolitis in infants <24 months — hypoxaemia, increased work of breathing, poor feeding', pop:'paed', maxAge:2, risk:2,
  d:{t:'text', text:'No routine drug therapy. Oxygen to keep SpO₂ ≥90–92%; nasal suction; enteral/IV fluids at two-thirds to full maintenance; trial of nebulised 3% saline in hospitalised infants'},
  fx:[{s:'3% sodium chloride for nebulisation (30 mg/mL)', c:30, u:'mg', p:'4 mL ampoule', b:'Hypersal 3% (Cipla), Nebusal 3%, Sodium Chloride 3% respules', r:'NEB', hl:1, own:{a:4,u:'ml',l:'Hypertonic (3%) saline 4 mL nebulised every 6–8 h — only as a TRIAL in hospitalised infants, and only with a bronchodilator if used repeatedly. Stop if there is no benefit.'}},
      {s:'Oxygen (nasal cannula 1–2 L/min; HFNC 2 L/kg/min up to 8 L/min)', c:1, u:'ml', p:'—', b:'Wall oxygen, HFNC device', r:'INHAL', own:{text:'Oxygen to keep SpO₂ ≥90–92%: nasal cannula 1–2 L/min, or HFNC 2 L/kg/min (up to 8 L/min) when the work of breathing is high. Oxygen, not drugs, is the mainstay of treatment.'}},
      {s:'Maintenance IV fluid (isotonic)', c:1, u:'ml', p:'bag', b:'DNS, 0.9% NaCl with 5% dextrose', r:'IV', own:{text:'IV isotonic fluid at two-thirds to full maintenance only if enteral feeding is unsafe. Avoid overhydration — SIADH is common. Nasogastric feeding is preferred when the respiratory rate allows.'}}],
  admin:'(1) Oxygen to maintain SpO₂ ≥90–92% (nasal cannula 1–2 L/min; HFNC 2 L/kg/min if the work of breathing is high). (2) Nasal suctioning/saline drops before feeds. (3) Fluids: enteral (NG) if safe, otherwise IV at maintenance, with careful avoidance of overhydration (SIADH is common). (4) Nebulised 3% saline 3–5 mL every 6–8 h may be trialled in hospitalised infants (mixed evidence). (5) Feeding support and parental education.',
  dil:'3% saline is used undiluted in the nebuliser; a bronchodilator may be given before the first dose to prevent bronchospasm.',
  warn:['DO NOT routinely give: bronchodilators (salbutamol/ipratropium), systemic or inhaled corticosteroids, adrenaline nebulisation, antibiotics (unless there is a proven bacterial co-infection), or chest physiotherapy — none improve outcomes and all cause harm.','Antibiotics are only indicated for proven co-infection (otitis media, pneumonia, UTI).','Palivizumab prophylaxis is restricted to high-risk infants (BPD, congenital heart disease, severe prematurity) and is not a treatment.','Watch for apnoea in infants <2 months, ex-preterms, and those with neuromuscular disease.','Admission criteria: SpO₂ <90–92% in air, poor feeding (<50% of normal), apnoea, moderate–severe respiratory distress, social concerns.'],
  ref:['AAP-BRONCHIOLITIS','NICE-NG9','IAP-BRONCHIOLITIS','BNFC','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY','NELSON','GHAI10','IAP-STG'] });

/* ================= MISCELLANEOUS ICU ================= */
R({ id:'insulin-glycaemic', n:'Insulin — ICU glycaemic control', sys:'endocrine', cls:'Short-acting insulin infusion',
  ind:'Persistent hyperglycaemia >180 mg/dL (10 mmol/L) in the critically ill; target 140–180 mg/dL (7.8–10 mmol/L)', pop:'all', risk:5, inf:true,
  d:{t:'unitskghr', lo:0.02, hi:0.1},
  diln:[{l:'50 units in 50 mL NS → 1 unit/mL (STANDARD 1:1 syringe)', amt:50, in:50, u:'units', bag:'50 mL 0.9% NaCl'},
        {l:'100 units in 100 mL NS → 1 unit/mL', amt:100, in:100, u:'units', bag:'100 mL 0.9% NaCl'}],
  fx:[{s:'100 IU/mL', c:100, u:'units', p:'10 mL vial (1000 units)', b:'Huminsulin R (Eli Lilly), Actrapid HM (Novo Nordisk), Wosulin R (Wockhardt), Recilin R', r:'IV', hl:1}],
  admin:'Start 0.02–0.05 units/kg/h (typically 2–4 units/h in an adult) when glucose is persistently >180 mg/dL; titrate by 1–2 units/h every 1 h using a validated protocol; target 140–180 mg/dL. Do NOT target 80–110 mg/dL (NICE-SUGAR: increased mortality from hypoglycaemia).',
  dil:'Always use 1 unit/mL in 0.9% NaCl; prime the line with 20 mL of the solution (insulin adsorbs to PVC); use the same concentration throughout the admission.',
  warn:['HYPOGLYCAEMIA is the main risk — check glucose hourly during titration, then every 2–4 h once stable, and every 1 h after any rate change. Check glucose hourly if the infusion rate changes or nutrition is interrupted.','STOP or reduce the infusion immediately if the nutrition feed or dextrose infusion is interrupted — this is the commonest cause of ICU hypoglycaemia.','Hypokalaemia — check K⁺ every 6–12 h and replace.','Never confuse the 100 IU/mL vial with the 40 IU/mL vial or with insulin analogues (aspart/glulisine are for SC use).','Do not use insulin syringes and infusion pumps interchangeably without verifying units/hour.','Use a validated paper or electronic protocol — ad hoc adjustments cause both hyper- and hypoglycaemia.'],
  ref:['ADA-INPATIENT','SCCM-GLUCOSE','NICE-SUGAR','ISCCM-ENDO','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'stress-ulcer-prophy', n:'Stress ulcer prophylaxis — who should get it', sys:'gi', cls:'Proton-pump inhibitor / H2-receptor antagonist',
  ind:'Mechanical ventilation >48 h, coagulopathy (platelets <50,000, INR >1.5, aPTT >2 × control), prior GI bleed/ulcer within 1 year, TBI (GCS ≤10) or spinal cord injury, burns >35% BSA, sepsis, high-dose corticosteroids + NSAIDs, major trauma/surgery, enteral feeding intolerance', pop:'adult', risk:2,
  d:{t:'mg', v:40, capDay:40, rep:'pantoprazole 40 mg IV/PO once daily (or ranitidine 50 mg IV q8h / famotidine 20 mg IV q12h with renal adjustment)'},
  fx:[{s:'40 mg pantoprazole vial', c:4, u:'mg', p:'reconstitute with 10 mL NS → 4 mg/mL', b:'Pan (Alkem), Pantocid (Sun), Pantop (Cipla)', r:'IV/PO', hl:1},
      {s:'40 mg pantoprazole tablet', c:40, u:'mg', p:'strip of 15', b:'Pan 40, Pantocid 40', r:'PO'},
      {s:'25 mg/mL famotidine', c:25, u:'mg', p:'2 mL ampoule (50 mg), 4 mL ampoule (100 mg)', b:'Famocid (Alkem), Famotidine IP — Intas/Neon; Famtin', r:'IV/PO', own:{a:20,u:'mg',l:'FAMOTIDINE 20 mg IV q12h (10 mg if CrCl <50 mL/min) — the H2-receptor alternative to a PPI.'}},
      {s:'25 mg/mL ranitidine', c:25, u:'mg', p:'2 mL ampoule (50 mg)', b:'Rantac (JB Chemicals), Ranitidine IP — availability restricted in some markets due to NDMA concerns', r:'IV/PO', own:{a:50,u:'mg',l:'RANITIDINE 50 mg IV q8h. Ranitidine has been withdrawn in many markets over NDMA impurities — check current Indian availability and prefer famotidine.'}}],
  admin:'Pantoprazole 40 mg IV/PO once daily (or esomeprazole 40 mg once daily). Alternatives: famotidine 20 mg IV q12h (10 mg if CrCl <50), ranitidine 50 mg IV q8h. Sucralfate 1 g PO/NG q6h is an option where acid suppression is undesirable. STOP prophylaxis as soon as the risk factors resolve and the patient is eating.',
  dil:'Reconstitute pantoprazole with 10 mL of NS; may be given IV over 2–15 min.',
  warn:['DO NOT give routine prophylaxis to all ICU patients — the SUP-ICU and PEPTIC trials show no mortality benefit and an increased risk of pneumonia and C. difficile infection.','PPIs: hypomagnesaemia, vitamin B12 deficiency, bone fracture, interstitial nephritis, small intestinal bacterial overgrowth, drug interactions (clopidogrel — use pantoprazole).','Enteral nutrition itself is protective — early enteral feeding reduces the need for pharmacological prophylaxis.','Ranitidine has been withdrawn or restricted in several countries due to NDMA contamination; famotidine is the preferred H2 antagonist.','Audit and de-prescribe daily — unnecessary PPI use is a marker of poor ICU stewardship.'],
  ref:['SUP-ICU','PEPTIC','ISCCM-SUP','SCCM-NUTRITION','BNF'] });

R({ id:'diclofenac-im', n:'Diclofenac IM / Nefopam — non-opioid analgesia', sys:'sedation', cls:'NSAID (IM) / non-opioid centrally acting analgesic',
  ind:'Renal and biliary colic, musculoskeletal pain, post-operative analgesia where opioids are undesirable; nefopam for opioid-sparing analgesia', pop:'adult', risk:3,
  d:{t:'mg', v:75, capDay:150, rep:'diclofenac 75 mg IM once or twice daily (max 2 days of IM therapy); nefopam 20 mg IV over 15 min every 8 h'},
  fx:[{s:'25 mg/mL diclofenac', c:25, u:'mg', p:'3 mL ampoule (75 mg) — IM ONLY (deep gluteal, alternate sides)', b:'Voveran (Novartis), Diclofenac IP — Neon/Intas; Diclonac, Voveran IM', r:'IM', hl:1},
      {s:'20 mg/mL nefopam', c:20, u:'mg', p:'1 mL ampoule (20 mg)', b:'Nefopam Hydrochloride IP — Neon/Intas; Rancet, Neopa', r:'IV/IM', own:{a:20,u:'mg',l:'NEFOPAM 20 mg IV diluted in 100 mL NS over 15 min every 8 h (or 20 mg IM). Max 90 mg/day. Avoid in seizure disorders, urinary retention and glaucoma; it causes orange-pink urine.'}},
      {s:'75 mg/mL diclofenac (some brands)', c:75, u:'mg', p:'1 mL ampoule', b:'Diclofenac 75 mg/mL', r:'IM'}],
  admin:'Diclofenac 75 mg DEEP IM into the upper outer quadrant of the buttock, alternating sides; maximum 2 consecutive days of IM therapy, then switch to oral. Nefopam 20 mg IV diluted in 100 mL NS over 15 min every 8 h (or 20 mg IM).',
  dil:'Diclofenac IM must NOT be given IV — it causes thrombosis and tissue damage. Nefopam MUST be diluted and infused slowly over ≥15 min (undiluted rapid IV injection causes nausea, tachycardia and seizures).',
  warn:['Diclofenac: GI bleeding and ulceration, AKI (avoid in hypovolaemia, CKD, heart failure, cirrhosis), cardiovascular risk with prolonged use, injection-site abscess and necrosis, bronchospasm in aspirin-sensitive asthma.','Nefopam: SEIZURES (avoid in epilepsy), tachycardia, urinary retention, anticholinergic effects, nausea; contraindicated with MAOIs and in closed-angle glaucoma.','Both are inappropriate in the ICU where renal function and volume status fluctuate — reassess daily.','Never combine two NSAIDs; add a PPI if GI risk factors are present.'],
  ref:['BNF','WHO-ANALGESIC','ISCCM-ANALGESIA'] });

R({ id:'dexamethasone-extubation', n:'Dexamethasone — prevention of post-extubation stridor', sys:'respiratory', cls:'Glucocorticoid',
  ind:'High-risk patients (prolonged intubation, large ETT, traumatic intubation, female sex, reintubation) — a cuff-leak test failure or a planned high-risk extubation', pop:'all', risk:3,
  d:{t:'mgkg', lo:0.15, hi:0.5, cap:20, rep:'0.15–0.5 mg/kg (adult 5–10 mg) IV every 6 h × 4 doses, starting at least 4 h BEFORE extubation'},
  fx:[{s:'4 mg/mL', c:4, u:'mg', p:'1 mL ampoule (4 mg), 2 mL ampoule (8 mg)', b:'Dexamethasone IP — Neon, Aristo; Dexona, Decdan', r:'IV/PO', hl:1},
      {s:'8 mg/mL', c:8, u:'mg', p:'2 mL ampoule (16 mg)', b:'Dexamethasone 8 mg/mL', r:'IV/IM'}],
  admin:'Adult: 5–10 mg IV every 6 h for 4 doses, with the FIRST DOSE AT LEAST 4 H BEFORE EXTUBATION (a single dose given immediately before extubation is ineffective). Children: 0.15–0.5 mg/kg (max 10 mg) IV every 6 h × 4 doses. Croup: 0.15–0.6 mg/kg as a single dose (max 10 mg).',
  dil:'Ready to use.',
  warn:['TIMING IS CRITICAL — dexamethasone needs ≥4 h to reduce laryngeal oedema.','Hyperglycaemia, infection risk with repeated doses.','Nebulised adrenaline 0.5 mL/kg (max 5 mL) is the treatment for established stridor; reintubate if it fails or recurs.','Perform a cuff-leak test before extubation in high-risk patients (a leak <110 mL or <15% of the tidal volume predicts stridor).','Do not delay extubation solely to complete a steroid course if the patient is otherwise ready.'],
  ref:['ATS-EXTUBATION','SCCM-AIRWAY','BNFC','NICE-CG25','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });

R({ id:'protamine-heparin-crri', n:'Regional citrate anticoagulation — calcium replacement (CRRT)', sys:'renal', cls:'Calcium replacement during extracorporeal citrate anticoagulation',
  ind:'Continuous renal replacement therapy with regional citrate anticoagulation — systemic ionised calcium must be maintained at 0.9–1.2 mmol/L', pop:'all', risk:5, inf:true,
  d:{t:'mmolkghr', lo:0.05, hi:0.1, text:'Systemic calcium infusion is titrated to the POST-FILTER/systemic ionised calcium (target 0.9–1.2 mmol/L), typically 0.05–0.1 mmol/kg/h of calcium'},
  diln:[{l:'10 g calcium gluconate in 100 mL NS → 100 mg/mL (≈0.225 mmol Ca²⁺/mL)', amt:10, in:100, u:'g', alt:{u:'mmol', amt:22.5}, bag:'100 mL 0.9% NaCl'},
        {l:'10 g calcium chloride in 100 mL NS → 100 mg/mL (≈68 mmol Ca²⁺/L) — CENTRAL LINE ONLY', amt:10, in:100, u:'g', alt:{u:'mmol', amt:68}, bag:'100 mL 0.9% NaCl'}],
  fx:[{s:'100 mg/mL (10%) calcium gluconate', c:100, u:'mg', alt:[{u:'mmol', c:0.225},{u:'mEq', c:0.45}], p:'10 mL ampoule (1 g = 2.25 mmol Ca²⁺) — 10 ampoules per 100 mL bag', b:'Calcium Gluconate IP — Neon, Samarth', r:'IV', hl:1},
      {s:'100 mg/mL (10%) calcium chloride', c:100, u:'mg', alt:[{u:'mmol', c:0.68},{u:'mEq', c:1.36}], p:'10 mL ampoule (1 g = 6.8 mmol Ca²⁺) — CENTRAL LINE ONLY', b:'Calcium Chloride IP — Neon, Samarth', r:'IV'},
      {s:'4% trisodium citrate (anticoagulant)', c:40, u:'mg', p:'3000 mL bag — availability in India is via compounding or ready-made CRRT fluids', b:'Trisodium Citrate 4% (compounded), Phoxillum/Prismacit Bie 4% (Baxter), Regional Citrate solutions', r:'CRRT-circuit', use:'fixed', give:'Run pre-filter at 1.2-1.5 x the blood flow rate. Target post-filter ionised calcium 0.25-0.40 mmol/L and systemic ionised calcium 0.9-1.2 mmol/L. A total/ionised calcium ratio >2.5 means citrate is accumulating - reduce or stop citrate.'}],
  admin:'Run 4% trisodium citrate pre-filter at 1.2–1.5 × the blood flow rate (target post-filter ionised calcium 0.25–0.40 mmol/L). Simultaneously infuse calcium (gluconate or chloride) into a SEPARATE systemic line, titrated to keep the systemic ionised calcium at 0.9–1.2 mmol/L. Check the systemic and post-filter ionised calcium, plus total calcium, at 0.5 h, 1 h, then 4–6 hourly.',
  dil:'Use separate, dedicated lines for citrate and calcium — never Y-site them together (precipitation).',
  warn:['CITRATE ACCUMULATION (total/ionised calcium ratio >2.5, rising total calcium with a falling ionised calcium, metabolic acidosis, worsening liver function) — occurs in liver failure, shock and severe hypoperfusion. Switch to heparin or no anticoagulation.','METABOLIC ALKALOSIS after citrate is metabolised to bicarbonate — reduce the CRRT replacement-fluid bicarbonate.','Hypocalcaemia (ionised <0.9) causes hypotension, arrhythmias and reduced contractility — increase the calcium infusion.','Hypercalcaemia (ionised >1.2) — reduce the calcium infusion.','Citrate is now the KDIGO-preferred anticoagulant for CRRT in patients without contraindications — it prolongs filter life and reduces bleeding compared with heparin.'],
  ref:['KDIGO-AKI','KDIGO-CRRT','ESICM-CRRT','ISCCM-CRRT','HARRIET-LANE','SINGH-DOSES','GUPTA-FORMULARY'] });
